  out=[]
  for x in rows:
   ids=[z[0] for z in c.execute('select user_id from reactions where message_id=? and emoji=?',(mid,x['emoji'])).fetchall()]
   out.append({'emoji':x['emoji'],'count':x['n'],'user_ids':ids})
 return js({'reactions':out})
'''
